INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'CREA.G2.CREATI.HOPPING', 'creative_activities', 2, 'Describe hopping and name its directions and floor patterns', ARRAY['CREA.G2.CREATI.HOPPING.a']::text[], 'The child says hopping is taking off and landing on the same one foot, tells it from jumping (two feet) and from skipping, names the directions (forward, backward, to the right, to the left) and the floor patterns (straight, curved, circular, zigzag). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: b) perform hopping in different directions for agility; c) make pattern formations while hopping in different directions for coordination.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'CREA.G2.CREATI.DRAWING_AND_PAINTING', 'creative_activities', 2, 'Identify texture and how a rubbing shows it', ARRAY['CREA.G2.CREATI.DRAWING_AND_PAINTING.a']::text[], 'The child says texture is how a surface feels or looks as if it would feel (rough, smooth, bumpy, ridged), names surfaces with each texture (tree bark, a leaf, a coin, a woven mat, a wall), and says a rubbing is made by laying thin paper on the surface and rubbing the side of a crayon over it. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: b) create texture on paper by rubbing on surfaces; c) apply texture on drawn shapes.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'CREA.G2.CREATI.DRAWING_AND_PAINTING', 'creative_activities', 2, 'Name regular shapes and how to paint them neatly with a brush', ARRAY['CREA.G2.CREATI.DRAWING_AND_PAINTING.d']::text[], 'The child names the regular shapes they paint (circle, square, triangle, rectangle), and says how to use a brush: dip only the tip, wipe the extra paint on the edge of the pot, paint inside the outline in one direction, and wash the brush before taking a new colour. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: d) paint regular shapes using a brush.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_activities', 2, 'Name the ways of creating rhythm', ARRAY['CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.a']::text[], 'The child names the ways of making rhythm in music (reciting words, clapping, tapping, stamping, humming) and picks the way being used in a short performance. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: b) imitate repetitive rhythmic sounds for rhythm awareness.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_activities', 2, 'Clap the rhythm of simple words by their parts', ARRAY['CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.c']::text[], 'The child says each part (syllable) of a word gets one clap, counts the claps for simple words (cat 1, ma-ma 2, ba-na-na 3, Nai-ro-bi 3), and matches a clapped pattern to the word or name it fits. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: c) recite/clap rhythmic patterns of simple words to develop a sense of rhythm; d) create rhythmic patterns based on simple words.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN', 'creative_activities', 2, 'Continue a printed shape pattern', ARRAY['CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.e']::text[], 'The child names the shapes in a printed pattern (circles, triangles, squares), says which part repeats, and says which shape comes next in a pattern such as circle, square, circle, square, or circle, circle, triangle. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: e) create simple shape patterns by printing.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'CREA.G2.CREATI.TURNING', 'creative_activities', 2, 'Name the directions and sizes of a body turn', ARRAY['CREA.G2.CREATI.TURNING.a']::text[], 'The child names a turn to the left and a turn to the right, says a half turn ends facing the back and a full turn ends facing the front again, and says which way they face after a turn or two turns put together. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: b) perform turning body in different directions for coordination.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC', 'CREA.G2.CREATI.MOSAIC', 'creative_activities', 2, 'Say what a mosaic is and the materials and tools used to make it', ARRAY['CREA.G2.CREATI.MOSAIC.a', 'CREA.G2.CREATI.MOSAIC.b']::text[], 'The child says a mosaic is a picture made of many small pieces of about the same size stuck close together with small gaps between them, names materials (coloured paper, seeds, eggshells, bottle tops, small stones) and tools (scissors, glue or paste, a brush), and tells a mosaic from a painting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: c) make a mosaic for self-expression.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'CREA.G2.CREATI.MELODY', 'creative_activities', 2, 'Tell similar from different tunes and show them with shapes', ARRAY['CREA.G2.CREATI.MELODY.a', 'CREA.G2.CREATI.MELODY.b']::text[], 'The child hears two short tunes and says if they are the same or different, and shows a song with shapes: the same shape for a tune that comes back, a different shape (circle, triangle, square) for a new tune. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS', 'CREA.G2.CREATI.MELODY', 'creative_activities', 2, 'Put new words to a tune the child knows', ARRAY['CREA.G2.CREATI.MELODY.c']::text[], 'The child says that when new words are put to a known tune the tune stays the same, the new words must fit the same number of notes and beats, and the words should make sense together (a song about washing hands to a tune the class knows). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.1.1), never as a phone question: c) improvise new words to existing tunes for self-expression.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST', 'creative_activities', 2, 'Identify Western singing games and their parts', ARRAY['CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.a']::text[], 'The child names Western-style singing games (Here we go round the mulberry bush, London Bridge is falling down, The farmer''s in his den, In and out the windows), and the parts of a singing game: the song, the game actions, the formation (a ring, a line, an arch), props and costumes, and the safety rules (good posture, holding hands gently, keeping the circle). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: b) sing appropriate game songs in Western style; c) use props in performing a singing game in Western style; d) perform singing games in Western style observing performance aspects.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK', 'CREA.G2.PERFOR.KICKING', 'creative_activities', 2, 'Name the parts of the leg used to kick a ball and how to kick in different directions', ARRAY['CREA.G2.PERFOR.KICKING.a']::text[], 'The child names the parts used to kick (the thigh, the knee, the lower leg, the inside of the foot, the top of the foot, the toes), says the inside of the foot gives a short, accurate kick, the standing foot goes beside the ball and the eyes stay on the ball, and names the directions of a kick (forward, backward, left, right). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: b) perform kicking a ball in different directions for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_', 'creative_activities', 2, 'Name plaiting materials and the steps of a three-strand plait', ARRAY['CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.a']::text[], 'The child names materials for plaiting a bracelet (threads, reused polythene strips, banana fibre, sisal), and says the steps of a three-strand plait: tie the three strands at the top, cross the right strand over the middle, then the left strand over the middle, repeat, and tie the end. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: b) make a single strand bracelet using the plaiting technique.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC', 'creative_activities', 2, 'Describe the egg roll and the directions it moves', ARRAY['CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.a']::text[], 'The child says in an egg roll the body is curled tight like an egg (knees to chest, arms holding the shins, chin tucked) and rolls sideways along the mat, to the left and to the right, and says markers show where to start and stop. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: c) improvise markers for use during performance of the egg roll and swan balance; d) perform the egg roll and swan balance in gymnastics for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC', 'creative_activities', 2, 'Name the body parts used in a swan balance', ARRAY['CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.b']::text[], 'The child says in a swan balance the child stands on one leg, leans the body forward, stretches the other leg straight out behind and spreads the arms like wings, with the head up, and holds still. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: d) perform the egg roll and swan balance in gymnastics for skill acquisition.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS', 'creative_activities', 2, 'Identify indigenous wind instruments and how they are played', ARRAY['CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.a']::text[], 'The child names wind instruments from indigenous Kenyan communities (flutes made from bamboo, reeds or gourds; horns such as the siwa), says the sound comes from blowing, and that a flute is played by holding it with the fingers over the holes and blowing gently. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: b) improvise a wind instrument using locally available materials; c) produce sound on an improvised musical wind instrument.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI', 'creative_activities', 2, 'Identify items made by coiling and the steps of the coil method', ARRAY['CREA.G2.PERFOR.MODELLING_COILING_TECHNI.a']::text[], 'The child names items made by coiling (pots, bowls, baskets, mats) and orders the coil method: roll long, even coils of clay, wind them round on a flat base, join each coil to the one below by pressing and smoothing, and smooth the sides. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: b) model items using the coil method.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'CREA.G2.PERFOR.SONGS', 'creative_activities', 2, 'Identify a topical song and say its message', ARRAY['CREA.G2.PERFOR.SONGS.a', 'CREA.G2.PERFOR.SONGS.b']::text[], 'The child says a topical song is about one topic (washing hands, road safety, keeping the school clean, caring for animals), names the topic of a song they know and says its message in their own words. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'CREA.G2.PERFOR.SONGS', 'creative_activities', 2, 'Name the performance techniques of a song', ARRAY['CREA.G2.PERFOR.SONGS.c']::text[], 'The child names the techniques of performing a song (the right tune, clear words, gestures that match the words, facial expressions that match the mood) and says which technique a performer forgot in a short story. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.2.1), never as a phone question: c) perform a topical song applying performance techniques.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST', 'creative_activities', 2, 'Identify the participants, costumes and props of a Western singing game', ARRAY['CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.a', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.b', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.c']::text[], 'The child names the participants of a Western singing game (the singers in the ring, the one in the middle such as the farmer, the two who make the bridge), the costumes they may wear and the props they use (a scarf, a hat, a hoop, a handkerchief), and tells a prop from a costume. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST', 'creative_activities', 2, 'Describe the message in a singing game', ARRAY['CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.d']::text[], 'The child says what a singing game is about (London Bridge: building and mending; Here we go round the mulberry bush: the jobs we do each day; The farmer''s in his den: a farm family and its animals) and what it teaches (working together, taking turns, daily routines). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 2, 'Recognise the water points in the school environment', ARRAY['CREA.G2.APPREC.WATER_SAFETY_AWARENESS.a']::text[], 'The child names the water points in the school environment (taps, water tanks, a well, a borehole, a pond, a drain or trench that fills with rain water) and says which can be dangerous to a small child. Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS', 'creative_activities', 2, 'Say how to apply water safety at school', ARRAY['CREA.G2.APPREC.WATER_SAFETY_AWARENESS.c']::text[], 'The child names water safety rules at school (do not play at the taps or tanks, close taps after use, wipe or avoid wet slippery floors, keep away from ponds and trenches, never climb water tanks, tell a teacher about an open tank or well). Evidence rule: at least four of the last five fresh questions right across at least two question forms, read aloud to the child where needed, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G2.RUBRIC.3.1), never as a phone question: b) perform singing games on water safety around water points in school.', '["pick the right answer","pick the right answer in a short story","spot the mistake in a friend''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'skill', 'essential', 'Jumping in different ways (Grade 1) comes before hopping on one foot in named directions. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'MATH.G1.GEOMET.LINES.IDENTIFY_LINES', 'skill', 'helpful', 'Telling straight from curved lines (Grade 1 Maths) is how the floor patterns are named. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'skill', 'essential', 'The materials and tools for colouring (Grade 1), crayons among them, are used to take rubbings. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'CREA.G1.CREATI.DRAWING.LINES', 'skill', 'helpful', 'Drawing lines in different directions (Grade 1) is how texture is added to drawn shapes. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_WAYS', 'skill', 'essential', 'Painting shapes with a brush (Grade 1) comes before painting regular shapes neatly. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'MATH.G2.GEOMET.SHAPES.NAME_SHAPES_ENV', 'skill', 'essential', 'Naming shapes in the environment (Grade 2 Maths) is how the regular shapes are named. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'CREA.G1.CREATI.RHYTHM.BEAT', 'skill', 'essential', 'Keeping a steady beat (Grade 1) is the ground every rhythm is made on. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'skill', 'essential', 'Body percussion (Grade 1) gives clapping, tapping and stamping as ways to make rhythm. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'CREA.G1.CREATI.RHYTHM.BODY_PERCUSSION', 'skill', 'essential', 'Clapping with body percussion (Grade 1) comes before clapping the parts of words. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'MATH.G1.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_50', 'skill', 'helpful', 'Counting (Grade 1 Maths) is used to count the claps in a word. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'CREA.G1.CREATI.PATTERN_MAKING.LETTER_NUMERAL_PATTERNS', 'skill', 'essential', 'Recognising patterns (Grade 1) comes before printing shape patterns. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'MATH.G1.GEOMET.SHAPES.SHAPE_PATTERNS_1', 'skill', 'essential', 'Making patterns of shapes (Grade 1 Maths) is the same idea of a part that repeats. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'skill', 'essential', 'Stretching in named directions (Grade 1) comes before turning the whole body in named directions. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'CREA.G1.CREATI.JUMPING.JUMP_WAYS', 'skill', 'essential', 'Jumping forward, backward, right and left (Grade 1) gives the direction words used for turns. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC', 'CREA.G1.CREATI.PAINTING_AND_COLOURING.PAINT_TOOLS', 'skill', 'essential', 'The materials and tools of art work (Grade 1) come before the pasting materials of a mosaic. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC', 'MATH.G2.GEOMET.SHAPES.NAME_SHAPES_ENV', 'skill', 'helpful', 'Naming shapes (Grade 2 Maths) is used to cut and place the small pieces. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'CREA.G1.CREATI.MELODY.LIKE_UNLIKE', 'skill', 'essential', 'Hearing like and unlike passages in short melodies (Grade 1) comes before naming similar and different tunes. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'CREA.G1.CREATI.MELODY.MELODIC_SOUNDS', 'skill', 'helpful', 'Telling melodic from non-melodic sounds (Grade 1) is the first step in listening to tunes. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS', 'CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'skill', 'essential', 'Knowing when a tune stays the same is needed to keep it while the words change. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'skill', 'helpful', 'Saying the message of an action song (Grade 1) helps the new words make sense. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'skill', 'essential', 'Kenyan singing games and their props (Grade 1) come before Western-style singing games. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'skill', 'helpful', 'Saying the message of an action song (Grade 1) is the start of understanding what a singing game is about. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.THROW_CATCH', 'skill', 'essential', 'Throwing and catching a ball (Grade 1) is the first ball skill before kicking. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK', 'CREA.G1.PERFOR.THROWING_AND_CATCHING.BALL_MATERIALS', 'skill', 'helpful', 'The materials of an improvised ball (Grade 1) make the ball that is kicked. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'CREA.G1.PERFOR.PAPER_CRAFT.PAPER_ITEMS', 'skill', 'essential', 'Pleating paper (Grade 1) trains the fingers to fold and cross in a fixed order. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'MATH.G1.NUMBER.PRE_NUMBER_ACTIVITIES.OBJECT_PATTERNS', 'skill', 'helpful', 'Making a repeating pattern (Grade 1 Maths) is the idea behind right, left, right, left in a plait. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'skill', 'essential', 'The log roll (Grade 1) is the first sideways roll; the egg roll curls the body tight. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'skill', 'helpful', 'Knowing the body parts used in stretching (Grade 1) is needed to name the parts that tuck in a roll. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'CREA.G1.PERFOR.LOG_ROLL_AND_T_BALANCE.ROLL_T', 'skill', 'essential', 'The T-balance (Grade 1) is the first one-leg balance; the swan leans further forward. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'CREA.G1.CREATI.STRETCHING.STRETCH', 'skill', 'helpful', 'Stretching the arms and legs (Grade 1) is needed to stretch out in the swan. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'CREA.G1.PERFOR.PERCUSSION_MUSICAL_INSTR.PERCUSSION', 'skill', 'essential', 'Naming percussion instruments (Grade 1) is the first sorting of instruments by how they make sound. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'CREA.G1.APPREC.MUSICAL_SOUNDS.SOUND_SOURCES', 'skill', 'helpful', 'Hearing sounds in the environment (Grade 1) comes before telling how a wind instrument sounds. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'CREA.G1.PERFOR.MODELLING.PINCH', 'skill', 'essential', 'Modelling by the pinch method (Grade 1) comes before building a pot from coils. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
