INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'skill', 'essential', 'Saying the message of an action song (Grade 1) comes before saying the message of a topical song. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'CREA.G1.APPREC.MUSICAL_SOUNDS.MOOD', 'skill', 'helpful', 'Describing the mood of a song (Grade 1) helps say what the song is telling us. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'skill', 'essential', 'Singing action songs with performance techniques (Grade 1) is where these techniques were first used. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'CREA.G1.CREATI.MELODY.ECHO', 'skill', 'helpful', 'Echoing a melodic pattern accurately (Grade 1) is the start of singing the right tune. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'skill', 'essential', 'Knowing Western singing games and their parts comes before naming who takes part and what they use. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'CREA.G1.PERFOR.SINGING_GAMES_KENYAN_STY.KENYAN_GAMES', 'skill', 'essential', 'Naming props in Kenyan singing games (Grade 1) is the same skill for Western games. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'skill', 'essential', 'Knowing the game and its song comes before saying what it is about. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'CREA.G1.PERFOR.SONGS.ACTION_SONG', 'skill', 'essential', 'Saying the message of an action song (Grade 1) is how the message of a game song is found. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_HOME', 'skill', 'essential', 'Water points at home (Grade 1) come before water points at school. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'ENVI.G2.RESOUR.WATER.a', 'outcome', 'helpful', 'Ways of storing water at school (Grade 2 Environmental Activities) name the tanks and containers that are water points. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'skill', 'essential', 'Knowing the water points at school comes before the safety rules for them. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'CREA.G1.APPREC.WATER_SAFETY_AWARENESS.WATER_SAFE_HOME', 'skill', 'essential', 'Water safety at home (Grade 1) grows into water safety at school. Proposed, to confirm by a CBC Creative Activities teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS.M_CAC2_HO_TWO_FEET', 'CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'Calls a two-footed jump a hop.', '{"question":"Wanjiru takes off on two feet and lands on two feet. Is that a hop?","wrong_answer":"yes","correct_answer":"no, it is a jump"}'::jsonb, 'In daily speech "hop" is used for any small jump.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Lift one foot and hop, then jump on two feet, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS.M_CAC2_HO_CHANGE_FOOT', 'CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'Lands on the other foot and calls it a hop.', '{"question":"In a hop, which foot do you land on?","wrong_answer":"the other foot","correct_answer":"the same foot you took off from"}'::jsonb, 'Running changes feet, so the child does the same.', 'Offer "the other foot" next to the right answer and ask the question again in a new context.', 'Hold a bean bag on the hopping knee and keep that foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS.M_CAC2_HO_LEFT_RIGHT', 'CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'Hops to their left when told ''right''.', '{"question":"Hop to your right. Which side do you go to?","wrong_answer":"my left side","correct_answer":"my right side"}'::jsonb, 'Right and left are still being learnt.', 'Offer "my left side" next to the right answer and ask the question again in a new context.', 'Tie a ribbon on the right wrist and hop that way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS.M_CAC2_HO_ZIGZAG', 'CREA.G2.CREATI.HOPPING.HOP_DIRECTIONS', 'Calls a wavy line a zigzag.', '{"question":"A line bends like a river with no corners. Is it a zigzag?","wrong_answer":"yes","correct_answer":"no, it is curved"}'::jsonb, 'Both lines change direction.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Chalk a zigzag with sharp corners beside a curve.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE.M_CAC2_TX_COLOUR', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'Names a colour when asked for a texture.', '{"question":"What is the texture of tree bark?","wrong_answer":"brown","correct_answer":"rough"}'::jsonb, 'Colour is what the child notices first.', 'Offer "brown" next to the right answer and ask the question again in a new context.', 'Close your eyes and touch the bark: what does it feel like?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE.M_CAC2_TX_SHINY_SMOOTH', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'Thinks only shiny things can be smooth.', '{"question":"Is a plastic plate rough or smooth?","wrong_answer":"rough, because it is not shiny","correct_answer":"smooth"}'::jsonb, 'The child links smooth with shiny glass and metal.', 'Offer "rough, because it is not shiny" next to the right answer and ask the question again in a new context.', 'Rub fingers over a matt plastic plate and a stone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE.M_CAC2_TX_RUB_TIP', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'Rubs with the point of the crayon and gets only lines.', '{"question":"Which part of the crayon do you use for a rubbing?","wrong_answer":"the point","correct_answer":"the long side"}'::jsonb, 'The child uses crayons only for drawing with the point.', 'Offer "the point" next to the right answer and ask the question again in a new context.', 'Peel a crayon and rub with its side over a leaf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE.M_CAC2_TX_THICK_PAPER', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.TEXTURE', 'Uses thick card for a rubbing.', '{"question":"Which paper is best for a rubbing?","wrong_answer":"thick card","correct_answer":"thin paper"}'::jsonb, 'Thick card seems stronger and better to the child.', 'Offer "thick card" next to the right answer and ask the question again in a new context.', 'Rub the same coin under card and under thin paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING.M_CAC2_BP_DIP_DEEP', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'Dips the whole brush into the pot up to the handle.', '{"question":"How much of the brush do you dip into the paint?","wrong_answer":"all of it, up to the handle","correct_answer":"only the tip"}'::jsonb, 'More paint seems better to the child.', 'Offer "all of it, up to the handle" next to the right answer and ask the question again in a new context.', 'Show a dripping brush and a brush dipped at the tip.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING.M_CAC2_BP_NO_WASH', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'Takes a new colour without washing the brush.', '{"question":"You finish with red and want yellow. What do you do first?","wrong_answer":"dip straight into yellow","correct_answer":"wash the brush"}'::jsonb, 'The child does not see the yellow being spoilt.', 'Offer "dip straight into yellow" next to the right answer and ask the question again in a new context.', 'Put a red brush in yellow and watch it turn orange.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING.M_CAC2_BP_TRIANGLE_SIDES', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'Paints a triangle with four sides.', '{"question":"How many sides does a triangle have?","wrong_answer":"four","correct_answer":"three"}'::jsonb, 'The child mixes the triangle with the square.', 'Offer "four" next to the right answer and ask the question again in a new context.', 'Count the sides of a triangle with a finger: one, two, three.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING.M_CAC2_BP_SCRUB', 'CREA.G2.CREATI.DRAWING_AND_PAINTING.BRUSH_PAINTING', 'Scrubs the brush back and forth over the paper.', '{"question":"How do you move the brush to paint a shape neatly?","wrong_answer":"scrub it back and forth hard","correct_answer":"stroke it gently in one direction inside the outline"}'::jsonb, 'Scrubbing is how the child cleans things.', 'Offer "scrub it back and forth hard" next to the right answer and ask the question again in a new context.', 'Show a scrubbed shape (torn paper) next to a smooth one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS.M_CAC2_RW_ONLY_DRUM', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'Thinks rhythm can only be made with a drum.', '{"question":"Can you make rhythm without a drum?","wrong_answer":"no","correct_answer":"yes, by clapping, tapping, stamping, humming or reciting"}'::jsonb, 'Drums are the instrument the child links with rhythm.', 'Offer "no" next to the right answer and ask the question again in a new context.', 'Make a rhythm with claps and stamps only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS.M_CAC2_RW_HUM_SING', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'Thinks humming is the same as singing the words.', '{"question":"What is humming?","wrong_answer":"singing the words loudly","correct_answer":"making the tune with the mouth closed"}'::jsonb, 'Both use the voice.', 'Offer "singing the words loudly" next to the right answer and ask the question again in a new context.', 'Sing a line, then hum it with lips closed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS.M_CAC2_RW_RECITE', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'Thinks reciting is not a way of making rhythm because there is no tune.', '{"question":"Children say a rhyme together in a steady beat. Are they making rhythm?","wrong_answer":"no, they are not singing","correct_answer":"yes, reciting makes rhythm"}'::jsonb, 'The child links rhythm only with music and tunes.', 'Offer "no, they are not singing" next to the right answer and ask the question again in a new context.', 'Recite a rhyme and clap the beat with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS.M_CAC2_RW_FAST_ONLY', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.RHYTHM_WAYS', 'Thinks rhythm means playing as fast as possible.', '{"question":"Is rhythm just playing as fast as you can?","wrong_answer":"yes","correct_answer":"no; it is a pattern of sounds in time"}'::jsonb, 'Exciting drumming is fast.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Clap a slow pattern and a fast pattern; both are rhythms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM.M_CAC2_WR_ONE_CLAP', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'Gives one clap for a whole word.', '{"question":"How many claps for \"ba-na-na\"?","wrong_answer":"one","correct_answer":"three"}'::jsonb, 'The child claps for whole words as in counting words.', 'Offer "one" next to the right answer and ask the question again in a new context.', 'Say the word slowly and clap each part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM.M_CAC2_WR_LETTERS', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'Claps once for each letter.', '{"question":"How many claps for \"cat\"?","wrong_answer":"three, one for each letter","correct_answer":"one"}'::jsonb, 'Letters are counted in reading lessons.', 'Offer "three, one for each letter" next to the right answer and ask the question again in a new context.', 'Say "cat" and feel your chin drop once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM.M_CAC2_WR_NAME_LONG', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'Thinks long names get more claps because they look long.', '{"question":"How many claps for \"Ann\"?","wrong_answer":"three, it has three letters","correct_answer":"one"}'::jsonb, 'The child judges by the written length.', 'Offer "three, it has three letters" next to the right answer and ask the question again in a new context.', 'Clap your name and a friend''s name and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM.M_CAC2_WR_UNEVEN', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.WORD_RHYTHM', 'Rushes the claps so the pattern does not match the word.', '{"question":"Clap \"Nai-ro-bi\". How should the claps sound?","wrong_answer":"as fast as possible","correct_answer":"even, one for each part as you say it"}'::jsonb, 'The child races to finish.', 'Offer "as fast as possible" next to the right answer and ask the question again in a new context.', 'Say and clap together slowly, then at normal speed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN.M_CAC2_SH_NEXT_SAME', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'Repeats the last shape instead of continuing the pattern.', '{"question":"Circle, square, circle, square, circle. What comes next?","wrong_answer":"circle","correct_answer":"square"}'::jsonb, 'The child copies the shape just seen.', 'Offer "circle" next to the right answer and ask the question again in a new context.', 'Say the pattern aloud and point: circle, square...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN.M_CAC2_SH_COLOUR_SHAPE', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'Continues by colour when the pattern is by shape.', '{"question":"A red circle, a red triangle, a red circle. What comes next?","wrong_answer":"a blue circle","correct_answer":"a red triangle"}'::jsonb, 'Colour catches the eye first.', 'Offer "a blue circle" next to the right answer and ask the question again in a new context.', 'Cover the colours and look only at the shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN.M_CAC2_SH_UNIT_TWO', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'Misses a repeating part of two of the same shape.', '{"question":"Circle, circle, triangle, circle, circle. What comes next?","wrong_answer":"circle","correct_answer":"triangle"}'::jsonb, 'The child expects every pattern to swap one by one.', 'Offer "circle" next to the right answer and ask the question again in a new context.', 'Put a ring round each repeating part: circle, circle, triangle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN.M_CAC2_SH_PRINT_SMUDGE', 'CREA.G2.CREATI.RHYTHM_AND_PATTERN_MAKIN.SHAPE_PATTERN', 'Slides the printing block across the paper.', '{"question":"How do you print a shape so it is clear?","wrong_answer":"slide the block across the paper","correct_answer":"press it straight down and lift it straight up"}'::jsonb, 'The child drags as with a crayon.', 'Offer "slide the block across the paper" next to the right answer and ask the question again in a new context.', 'Print once by pressing and once by sliding; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS.M_CAC2_TU_HALF_SIDE', 'CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'Thinks a half turn ends facing the side.', '{"question":"You face the board and make a half turn. Where do you face?","wrong_answer":"the window at the side","correct_answer":"the back of the room"}'::jsonb, 'The child mixes a half turn with a quarter turn.', 'Offer "the window at the side" next to the right answer and ask the question again in a new context.', 'Face the board, turn slowly and stop when you see the back wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS.M_CAC2_TU_FULL_BACK', 'CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'Thinks a full turn ends facing the back.', '{"question":"You face the board and make a full turn. Where do you face?","wrong_answer":"the back of the room","correct_answer":"the board again"}'::jsonb, '"Full" sounds like as far as you can go.', 'Offer "the back of the room" next to the right answer and ask the question again in a new context.', 'Turn all the way round until you see the board again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS.M_CAC2_TU_LEFT_RIGHT', 'CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'Turns right when told to turn left.', '{"question":"Turn to your left. Which shoulder goes back?","wrong_answer":"the left shoulder goes forward","correct_answer":"the left shoulder goes back as you turn left"}'::jsonb, 'Left and right are still mixed up.', 'Offer "the left shoulder goes forward" next to the right answer and ask the question again in a new context.', 'Hold up the left hand in an L shape before turning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.TURNING.TURN_DIRECTIONS.M_CAC2_TU_TWO_HALVES', 'CREA.G2.CREATI.TURNING.TURN_DIRECTIONS', 'Thinks two half turns leave you facing the back.', '{"question":"You make two half turns. Where do you face?","wrong_answer":"the back","correct_answer":"the front again"}'::jsonb, 'The child counts only the last turn.', 'Offer "the back" next to the right answer and ask the question again in a new context.', 'Make one half turn, say where you face, then another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC.M_CAC2_MO_PAINTING', 'CREA.G2.CREATI.MOSAIC.MOSAIC', 'Calls a painted picture a mosaic.', '{"question":"Which picture is a mosaic?","wrong_answer":"a picture painted with a brush","correct_answer":"a picture made of many small pieces stuck close together"}'::jsonb, 'All finished pictures look alike to the child.', 'Offer "a picture painted with a brush" next to the right answer and ask the question again in a new context.', 'Touch a mosaic and feel the small pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC.M_CAC2_MO_BIG_PIECES', 'CREA.G2.CREATI.MOSAIC.MOSAIC', 'Uses a few big pieces and calls it a mosaic.', '{"question":"Do you make a mosaic with big pieces or small pieces?","wrong_answer":"big pieces","correct_answer":"many small pieces"}'::jsonb, 'Big pieces finish the picture faster.', 'Offer "big pieces" next to the right answer and ask the question again in a new context.', 'Compare a picture of three big pieces with one of many small pieces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC.M_CAC2_MO_OVERLAP', 'CREA.G2.CREATI.MOSAIC.MOSAIC', 'Piles the pieces on top of each other.', '{"question":"How do you place the pieces in a mosaic?","wrong_answer":"on top of each other","correct_answer":"side by side with small gaps"}'::jsonb, 'The child wants to cover every bit of paper.', 'Offer "on top of each other" next to the right answer and ask the question again in a new context.', 'Place pieces side by side and point to the small gaps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MOSAIC.MOSAIC.M_CAC2_MO_TOOL_MATERIAL', 'CREA.G2.CREATI.MOSAIC.MOSAIC', 'Calls scissors a material for a mosaic.', '{"question":"Are scissors a material or a tool in mosaic making?","wrong_answer":"a material","correct_answer":"a tool"}'::jsonb, 'The child has not yet sorted things used up from things used to work.', 'Offer "a material" next to the right answer and ask the question again in a new context.', 'Sort cards: what is used up (paper, seeds) and what helps you work (scissors, brush).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT.M_CAC2_SD_WORDS', 'CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'Says two tunes are different because the words differ.', '{"question":"Two lines have the same tune but different words. Are the tunes the same?","wrong_answer":"no, different","correct_answer":"yes, the same"}'::jsonb, 'The child listens to the words, not the tune.', 'Offer "no, different" next to the right answer and ask the question again in a new context.', 'Hum both lines without words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT.M_CAC2_SD_SHAPE_SAME', 'CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'Gives every line a new shape even when the tune comes back.', '{"question":"The first tune comes back again. Which shape do you draw?","wrong_answer":"a new shape","correct_answer":"the same shape as before"}'::jsonb, 'The child thinks each line needs its own shape.', 'Offer "a new shape" next to the right answer and ask the question again in a new context.', 'Sing the song and point to the shape each time the first tune returns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT.M_CAC2_SD_LOUD_DIFF', 'CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'Says a tune is different when it is only louder.', '{"question":"The same tune is sung louder. Is it a different tune?","wrong_answer":"yes","correct_answer":"no, it is the same tune sung louder"}'::jsonb, 'Loudness changes the feel, so the child thinks the tune changed.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Sing it softly and loudly; ask if the notes moved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.SAME_DIFFERENT.M_CAC2_SD_SHAPE_MEANING', 'CREA.G2.CREATI.MELODY.SAME_DIFFERENT', 'Thinks a circle always means a happy tune.', '{"question":"In our song we drew a circle, a triangle, then a circle. What does the second circle show?","wrong_answer":"a happy part","correct_answer":"the first tune coming back"}'::jsonb, 'The child gives shapes their own meaning.', 'Offer "a happy part" next to the right answer and ask the question again in a new context.', 'Say: the shape only tells same or different.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS.M_CAC2_NW_CHANGE_TUNE', 'CREA.G2.CREATI.MELODY.NEW_WORDS', 'Changes the tune when singing new words.', '{"question":"You put new words to a song you know. What happens to the tune?","wrong_answer":"it changes too","correct_answer":"it stays the same"}'::jsonb, 'New words feel like a new song.', 'Offer "it changes too" next to the right answer and ask the question again in a new context.', 'Sing the old words, then the new words, while humming partners keep the tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS.M_CAC2_NW_TOO_MANY', 'CREA.G2.CREATI.MELODY.NEW_WORDS', 'Squeezes too many words into a line.', '{"question":"The line has four notes. How many word parts fit?","wrong_answer":"as many as you like","correct_answer":"about four, one for each note"}'::jsonb, 'The child does not match words to notes.', 'Offer "as many as you like" next to the right answer and ask the question again in a new context.', 'Clap the notes, then clap the new words, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS.M_CAC2_NW_NO_SENSE', 'CREA.G2.CREATI.MELODY.NEW_WORDS', 'Puts any words in, even if they make no sense together.', '{"question":"Do the new words of a song need to make sense?","wrong_answer":"no, any words will do","correct_answer":"yes, they should say something about one idea"}'::jsonb, 'The child focuses on fitting the beat only.', 'Offer "no, any words will do" next to the right answer and ask the question again in a new context.', 'Sing a nonsense line and a sensible one; ask which tells us something.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.CREATI.MELODY.NEW_WORDS.M_CAC2_NW_NEW_SONG_NAME', 'CREA.G2.CREATI.MELODY.NEW_WORDS', 'Thinks you cannot use a song someone else wrote for new words.', '{"question":"Can you sing new words about washing hands to a tune you already know?","wrong_answer":"no, songs cannot change","correct_answer":"yes"}'::jsonb, 'The child sees songs as fixed.', 'Offer "no, songs cannot change" next to the right answer and ask the question again in a new context.', 'Sing a hand-washing verse to a tune the class knows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES.M_CAC2_SG_NO_SONG', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'Thinks a singing game is a game with no song.', '{"question":"What makes a game a singing game?","wrong_answer":"it has a ball","correct_answer":"the players sing a song while they play"}'::jsonb, 'The child knows games mostly from ball games.', 'Offer "it has a ball" next to the right answer and ask the question again in a new context.', 'Play a game silently, then with its song.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES.M_CAC2_SG_FORMATION', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'Thinks every singing game is played in a line.', '{"question":"In which formation is \"Here we go round the mulberry bush\" played?","wrong_answer":"in a straight line","correct_answer":"in a ring (circle)"}'::jsonb, 'Lines are the formation the child knows from assembly.', 'Offer "in a straight line" next to the right answer and ask the question again in a new context.', 'Hold hands and walk round in a ring while singing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES.M_CAC2_SG_KENYAN', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'Calls a Kenyan singing game a Western one.', '{"question":"Is \"London Bridge is falling down\" a Kenyan or a Western singing game?","wrong_answer":"Kenyan","correct_answer":"Western"}'::jsonb, 'All singing games learnt at school seem the same.', 'Offer "Kenyan" next to the right answer and ask the question again in a new context.', 'Sort game cards into Kenyan and Western.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES.M_CAC2_SG_PULL', 'CREA.G2.PERFOR.SINGING_GAMES_WESTERN_ST.WESTERN_GAMES', 'Pulls hard on hands in a ring game to win.', '{"question":"In a ring game, how do you hold hands?","wrong_answer":"tightly, pulling others along","correct_answer":"gently, keeping the ring"}'::jsonb, 'The child thinks every game is a contest.', 'Offer "tightly, pulling others along" next to the right answer and ask the question again in a new context.', 'Show how pulling makes someone fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK.M_CAC2_KI_TOES', 'CREA.G2.PERFOR.KICKING.KICK', 'Thinks the toes give the best, most accurate kick.', '{"question":"Which part of the foot gives a short, accurate kick?","wrong_answer":"the toes","correct_answer":"the inside of the foot"}'::jsonb, 'Toe-poking is what young children do first.', 'Offer "the toes" next to the right answer and ask the question again in a new context.', 'Kick to a partner with the toes and then with the inside of the foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK.M_CAC2_KI_STANDING_FOOT', 'CREA.G2.PERFOR.KICKING.KICK', 'Puts the standing foot far behind the ball.', '{"question":"Where do you put your standing foot when you kick?","wrong_answer":"far behind the ball","correct_answer":"beside the ball"}'::jsonb, 'The child takes a big run and stops early.', 'Offer "far behind the ball" next to the right answer and ask the question again in a new context.', 'Put a bottle top beside the ball for the standing foot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK.M_CAC2_KI_ARM', 'CREA.G2.PERFOR.KICKING.KICK', 'Names the arm as a part used in kicking.', '{"question":"Which of these is used to kick a ball: the arm or the knee?","wrong_answer":"the arm","correct_answer":"the knee"}'::jsonb, 'The arms swing when kicking, so the child names them.', 'Offer "the arm" next to the right answer and ask the question again in a new context.', 'Point to the thigh, knee, lower leg and foot while kicking slowly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.KICKING.KICK.M_CAC2_KI_LOOK_UP', 'CREA.G2.PERFOR.KICKING.KICK', 'Looks at the goal instead of the ball when kicking.', '{"question":"Where do your eyes look as your foot touches the ball?","wrong_answer":"at the goal","correct_answer":"at the ball"}'::jsonb, 'The child wants to see where the ball will go.', 'Offer "at the goal" next to the right answer and ask the question again in a new context.', 'Kick while looking away, then while watching the ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT.M_CAC2_PL_TWO_STRANDS', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'Tries to plait with two strands.', '{"question":"How many strands do you need for a simple plait?","wrong_answer":"two","correct_answer":"three"}'::jsonb, 'Two strands are easier to hold.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'Try to plait two strands; then add a third.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT.M_CAC2_PL_SAME_SIDE', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'Keeps crossing from the same side.', '{"question":"You crossed the right strand over the middle. Which strand crosses next?","wrong_answer":"the right strand again","correct_answer":"the left strand"}'::jsonb, 'The child repeats the last move.', 'Offer "the right strand again" next to the right answer and ask the question again in a new context.', 'Say "right over middle, left over middle" with each cross.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT.M_CAC2_PL_NO_TIE', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'Starts plaiting without tying the top.', '{"question":"What do you do before you start to plait?","wrong_answer":"start plaiting straight away","correct_answer":"tie the three strands together at the top"}'::jsonb, 'The child is eager to start.', 'Offer "start plaiting straight away" next to the right answer and ask the question again in a new context.', 'Try plaiting loose strands; they slip apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT.M_CAC2_PL_MATERIAL', 'CREA.G2.PERFOR.PLAITED_ORNAMENT_SINGLE_.PLAIT', 'Thinks only wool or thread can be plaited.', '{"question":"Can you plait a bracelet from banana fibre?","wrong_answer":"no, only thread","correct_answer":"yes"}'::jsonb, 'The child has seen plaiting only with wool or hair.', 'Offer "no, only thread" next to the right answer and ask the question again in a new context.', 'Show banana fibre, sisal and polythene strips plaited.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL.M_CAC2_ER_STRETCHED', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'Rolls with the body stretched out and calls it an egg roll.', '{"question":"In an egg roll, is your body stretched or curled?","wrong_answer":"stretched out","correct_answer":"curled up tight like an egg"}'::jsonb, 'The log roll of Grade 1 was stretched.', 'Offer "stretched out" next to the right answer and ask the question again in a new context.', 'Hug your knees to your chest and rock.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL.M_CAC2_ER_FORWARD', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'Thinks the egg roll goes forward over the head.', '{"question":"Which way does an egg roll move?","wrong_answer":"forward over the head","correct_answer":"sideways, to the left or right"}'::jsonb, 'Forward rolls are the roll seen most often.', 'Offer "forward over the head" next to the right answer and ask the question again in a new context.', 'Lie curled on your side and roll to the left along the mat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL.M_CAC2_ER_LET_GO', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'Lets go of the shins in the middle of the roll.', '{"question":"In an egg roll, what do your arms do?","wrong_answer":"let go and push the floor","correct_answer":"hold the shins all the way"}'::jsonb, 'The child reaches out to stop rolling.', 'Offer "let go and push the floor" next to the right answer and ask the question again in a new context.', 'Roll slowly while counting, holding the shins.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL.M_CAC2_ER_MARKER', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.EGG_ROLL', 'Thinks markers are for decoration.', '{"question":"What are the markers for in an egg roll?","wrong_answer":"to make the mat pretty","correct_answer":"to show where to start and stop"}'::jsonb, 'The child sees markers as coloured objects.', 'Offer "to make the mat pretty" next to the right answer and ask the question again in a new context.', 'Put markers at each end of the mat and roll between them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN.M_CAC2_SW_TWO_FEET', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'Stands on two feet in a swan balance.', '{"question":"How many feet do you stand on in a swan balance?","wrong_answer":"two","correct_answer":"one"}'::jsonb, 'The child is afraid of falling.', 'Offer "two" next to the right answer and ask the question again in a new context.', 'Hold a wall, lift one leg back, then let go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN.M_CAC2_SW_LEG_FRONT', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'Lifts the free leg in front.', '{"question":"In a swan balance, where does the free leg go?","wrong_answer":"out in front","correct_answer":"straight out behind"}'::jsonb, 'Lifting a knee in front is easier.', 'Offer "out in front" next to the right answer and ask the question again in a new context.', 'Look at a picture of a swan: the tail is behind.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN.M_CAC2_SW_ARMS_DOWN', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'Keeps the arms at the sides.', '{"question":"What do the arms do in a swan balance?","wrong_answer":"stay at the sides","correct_answer":"spread out like wings"}'::jsonb, 'The child does not see the arms as part of the balance.', 'Offer "stay at the sides" next to the right answer and ask the question again in a new context.', 'Try to balance with arms down, then with arms spread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN.M_CAC2_SW_T_SAME', 'CREA.G2.PERFOR.EGG_ROLL_AND_SWAN_BALANC.SWAN', 'Thinks the swan balance is the same as the T-balance.', '{"question":"Is the swan balance the same as the T-balance?","wrong_answer":"yes","correct_answer":"no; in the swan the body leans forward with the head up and arms like wings"}'::jsonb, 'Both balances are on one leg.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Do a T-balance, then a swan, and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND.M_CAC2_WI_DRUM', 'CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'Calls a drum a wind instrument because you can blow on it.', '{"question":"Is a drum a wind instrument?","wrong_answer":"yes","correct_answer":"no, it is a percussion instrument; you hit it"}'::jsonb, 'The child knows "wind" as blowing air at anything.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Blow on a drum: no sound. Hit it: sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND.M_CAC2_WI_BLOW_HARD', 'CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'Blows as hard as possible into a flute.', '{"question":"How do you blow a flute?","wrong_answer":"as hard as you can","correct_answer":"gently and steadily"}'::jsonb, 'Hard blowing seems to give a bigger sound.', 'Offer "as hard as you can" next to the right answer and ask the question again in a new context.', 'Blow hard (a squeak) and gently (a clear note).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND.M_CAC2_WI_HOLES', 'CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'Thinks the holes on a flute are only decoration.', '{"question":"What are the holes on a flute for?","wrong_answer":"decoration","correct_answer":"covering them with fingers changes the note"}'::jsonb, 'The child has not seen a flute played.', 'Offer "decoration" next to the right answer and ask the question again in a new context.', 'Cover and uncover a hole while blowing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND.M_CAC2_WI_SHARE', 'CREA.G2.PERFOR.WIND_MUSICAL_INSTRUMENTS.WIND', 'Shares a flute without cleaning it.', '{"question":"Your friend wants to play your flute. What do you do first?","wrong_answer":"give it straight away","correct_answer":"clean the mouthpiece first"}'::jsonb, 'The child does not link sharing mouthpieces with germs.', 'Offer "give it straight away" next to the right answer and ask the question again in a new context.', 'Show how to wipe the mouthpiece with a clean cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL.M_CAC2_CO_THICK_THIN', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'Rolls coils that are thick in one place and thin in another.', '{"question":"How should the coils for a pot be?","wrong_answer":"any thickness","correct_answer":"the same thickness all along"}'::jsonb, 'The child presses harder at one end.', 'Offer "any thickness" next to the right answer and ask the question again in a new context.', 'Roll with flat palms moving out from the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL.M_CAC2_CO_NO_JOIN', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'Stacks coils without joining them.', '{"question":"After placing a coil on top of another, what do you do?","wrong_answer":"nothing","correct_answer":"press and smooth it onto the coil below"}'::jsonb, 'The child thinks the coils stay because they look in place.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Lift a pot with unjoined coils: it falls apart.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL.M_CAC2_CO_NO_BASE', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'Starts coiling without a flat base.', '{"question":"What do you make first for a coil pot?","wrong_answer":"the top","correct_answer":"a flat base"}'::jsonb, 'The child starts with the walls they can see.', 'Offer "the top" next to the right answer and ask the question again in a new context.', 'Make a flat round base and wind the first coil round it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL.M_CAC2_CO_PINCH', 'CREA.G2.PERFOR.MODELLING_COILING_TECHNI.COIL', 'Says a coil pot is made by pinching.', '{"question":"How is a coil pot made?","wrong_answer":"by pinching a ball of clay","correct_answer":"by rolling long coils and winding them round"}'::jsonb, 'The pinch method was learnt in Grade 1.', 'Offer "by pinching a ball of clay" next to the right answer and ask the question again in a new context.', 'Make a pinch pot and a coil pot side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE.M_CAC2_SM_TITLE', 'CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'Gives the first line of the song as its message.', '{"question":"What is the message of a song about washing hands?","wrong_answer":"it repeats the first line","correct_answer":"wash your hands to keep germs away"}'::jsonb, 'Repeating words is easier than saying the idea.', 'Offer "it repeats the first line" next to the right answer and ask the question again in a new context.', 'Ask: what does the song want us to do?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE.M_CAC2_SM_TOPICAL', 'CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'Thinks a topical song is any song with a nice tune.', '{"question":"What is a topical song?","wrong_answer":"any song with a nice tune","correct_answer":"a song about one topic, such as road safety"}'::jsonb, 'The child does not know the word "topic".', 'Offer "any song with a nice tune" next to the right answer and ask the question again in a new context.', 'Sort songs by what they are about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE.M_CAC2_SM_TOPIC_MIX', 'CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'Takes the most repeated word in a song as its topic ("looking" instead of road safety).', '{"question":"A song says \"look right, look left, then cross\". What is its topic?","wrong_answer":"looking at things","correct_answer":"road safety"}'::jsonb, 'The child picks the most repeated word.', 'Offer "looking at things" next to the right answer and ask the question again in a new context.', 'Ask: where would you do this?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_MESSAGE.M_CAC2_SM_ONLY_FUN', 'CREA.G2.PERFOR.SONGS.SONG_MESSAGE', 'Thinks songs are only for fun and have no message.', '{"question":"Can a song teach us something?","wrong_answer":"no, songs are just for fun","correct_answer":"yes, songs carry messages"}'::jsonb, 'The child sings for play.', 'Offer "no, songs are just for fun" next to the right answer and ask the question again in a new context.', 'Sing a hygiene song and ask what it teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES.M_CAC2_ST_LOUDEST', 'CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'Thinks singing loudest is the best technique.', '{"question":"What makes a song performed well?","wrong_answer":"singing the loudest","correct_answer":"the right tune, clear words, matching gestures and faces"}'::jsonb, 'The loudest singer is noticed most.', 'Offer "singing the loudest" next to the right answer and ask the question again in a new context.', 'Compare a shouted song with a clear, well-acted one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES.M_CAC2_ST_FACE_MISMATCH', 'CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'Smiles while singing a sad song.', '{"question":"You sing a sad song. What should your face show?","wrong_answer":"a big smile","correct_answer":"a sad face"}'::jsonb, 'Children are told to smile when performing.', 'Offer "a big smile" next to the right answer and ask the question again in a new context.', 'Sing a sad line with a smile and a sad face; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES.M_CAC2_ST_MUMBLE', 'CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'Thinks words do not need to be clear if the tune is right.', '{"question":"Why must words be clear when you sing?","wrong_answer":"they do not need to be","correct_answer":"so the listeners understand the message"}'::jsonb, 'The child focuses on the tune.', 'Offer "they do not need to be" next to the right answer and ask the question again in a new context.', 'Mumble a line and ask the class what you said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES.M_CAC2_ST_RANDOM_GESTURE', 'CREA.G2.PERFOR.SONGS.SONG_TECHNIQUES', 'Makes any gesture, not one that matches the words.', '{"question":"The song says \"the sun is high\". Which gesture fits?","wrong_answer":"clapping","correct_answer":"pointing up high"}'::jsonb, 'Any movement feels like a gesture.', 'Offer "clapping" next to the right answer and ask the question again in a new context.', 'Act each line and ask if the action shows the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS.M_CAC2_GP_PROP_COSTUME', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'Calls a hat worn by the farmer a prop.', '{"question":"In \"The farmer''s in his den\", the farmer wears a hat. Is the hat a costume or a prop?","wrong_answer":"a prop","correct_answer":"a costume, because it is worn"}'::jsonb, 'The child has not yet sorted worn things from held things.', 'Offer "a prop" next to the right answer and ask the question again in a new context.', 'Sort cards: things worn (costume) and things held or used (props).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS.M_CAC2_GP_AUDIENCE', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'Counts the audience as participants.', '{"question":"Who are the participants in a singing game?","wrong_answer":"everyone watching","correct_answer":"the children playing and singing in the game"}'::jsonb, 'Everyone present seems part of it.', 'Offer "everyone watching" next to the right answer and ask the question again in a new context.', 'Ask: who is singing and moving?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS.M_CAC2_GP_NO_PROPS', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'Thinks a singing game must always have props.', '{"question":"Can a singing game be played without props?","wrong_answer":"no","correct_answer":"yes; props are used in some games"}'::jsonb, 'The class game used props.', 'Offer "no" next to the right answer and ask the question again in a new context.', 'Play a ring game with no props.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS.M_CAC2_GP_BRIDGE', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_PARTS', 'Thinks everyone in London Bridge makes the bridge.', '{"question":"In \"London Bridge\", who makes the bridge?","wrong_answer":"all the children","correct_answer":"two children joining hands up high"}'::jsonb, 'The child focuses on the whole group.', 'Offer "all the children" next to the right answer and ask the question again in a new context.', 'Watch the game: count who holds the arch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE.M_CAC2_GM_ACTIONS', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'Describes the actions when asked for the message.', '{"question":"What is the message of \"Here we go round the mulberry bush\"?","wrong_answer":"we walk round in a ring","correct_answer":"the jobs we do every day, like washing and sweeping"}'::jsonb, 'The actions are easier to describe than the idea.', 'Offer "we walk round in a ring" next to the right answer and ask the question again in a new context.', 'Ask: what jobs does each verse show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE.M_CAC2_GM_REAL_BRIDGE', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'Thinks London Bridge is about a bridge in Kenya.', '{"question":"Where is London Bridge in the song?","wrong_answer":"in our town","correct_answer":"in London, in England, far away"}'::jsonb, 'The child places songs in their own world.', 'Offer "in our town" next to the right answer and ask the question again in a new context.', 'Show London on a map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE.M_CAC2_GM_NO_LESSON', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'Thinks singing games teach nothing.', '{"question":"What can a singing game teach?","wrong_answer":"nothing, it is only play","correct_answer":"to work together and take turns"}'::jsonb, 'Games feel only like fun.', 'Offer "nothing, it is only play" next to the right answer and ask the question again in a new context.', 'Ask what happens if one child does not take turns.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE.M_CAC2_GM_FARMER', 'CREA.G2.APPREC.SINGING_GAMES_WESTERN_ST.GAME_MESSAGE', 'Thinks "The farmer''s in his den" is about a wild animal''s den.', '{"question":"What is \"The farmer''s in his den\" about?","wrong_answer":"a lion in its den","correct_answer":"a farmer choosing a family and animals"}'::jsonb, 'The child knows "den" as an animal''s home.', 'Offer "a lion in its den" next to the right answer and ask the question again in a new context.', 'Sing the verses: the farmer wants a wife, a child, a dog.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS.M_CAC2_WP_ONLY_RIVER', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'Thinks a school has no water points if there is no river.', '{"question":"Name a water point in a school.","wrong_answer":"there are none","correct_answer":"a tap, a tank or a well"}'::jsonb, 'The child thinks of water points as rivers and lakes.', 'Offer "there are none" next to the right answer and ask the question again in a new context.', 'Walk round the school and count the taps and tanks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS.M_CAC2_WP_TRENCH', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'Thinks a trench full of rain water is not a water point.', '{"question":"After rain, a trench fills with water. Is it a water point to be careful at?","wrong_answer":"no, it is only a trench","correct_answer":"yes"}'::jsonb, 'The trench is dry most of the time.', 'Offer "no, it is only a trench" next to the right answer and ask the question again in a new context.', 'Look at the trench after rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS.M_CAC2_WP_TAP_SAFE', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'Thinks taps can never be dangerous.', '{"question":"How can the area round a tap be dangerous?","wrong_answer":"it cannot","correct_answer":"the floor gets wet and slippery"}'::jsonb, 'A tap seems small and safe.', 'Offer "it cannot" next to the right answer and ask the question again in a new context.', 'Pour water on a smooth floor and walk carefully on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS.M_CAC2_WP_TANK_CLIMB', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.WATER_POINTS', 'Thinks climbing a water tank is a good game.', '{"question":"Is it safe to climb on a water tank?","wrong_answer":"yes, it is fun","correct_answer":"no, you could fall or fall in"}'::jsonb, 'Tanks look like a climbing frame.', 'Offer "yes, it is fun" next to the right answer and ask the question again in a new context.', 'Look at how high and open a tank top is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL.M_CAC2_SS_TAP_OPEN', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'Leaves the tap running after use.', '{"question":"You finish washing your hands. What do you do?","wrong_answer":"leave the tap running for the next child","correct_answer":"close the tap"}'::jsonb, 'The child wants to help the next person.', 'Offer "leave the tap running for the next child" next to the right answer and ask the question again in a new context.', 'Show the puddle a running tap makes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL.M_CAC2_SS_RUN_WET', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'Runs across a wet floor.', '{"question":"The floor near the tap is wet. What do you do?","wrong_answer":"run across quickly","correct_answer":"walk slowly or go round it"}'::jsonb, 'Running seems quicker and safer.', 'Offer "run across quickly" next to the right answer and ask the question again in a new context.', 'Watch a toy slide on a wet surface.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL.M_CAC2_SS_TELL', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'Keeps quiet about an open tank.', '{"question":"You see a tank with its lid off. What do you do?","wrong_answer":"nothing","correct_answer":"tell a teacher"}'::jsonb, 'The child thinks it is not their job.', 'Offer "nothing" next to the right answer and ask the question again in a new context.', 'Role play telling a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL.M_CAC2_SS_SPLASH', 'CREA.G2.APPREC.WATER_SAFETY_AWARENESS.SAFETY_SCHOOL', 'Thinks splashing friends at the tap is harmless.', '{"question":"Is it all right to splash friends at the tap?","wrong_answer":"yes, it is play","correct_answer":"no, it wastes water and makes the floor slippery"}'::jsonb, 'Splashing is fun.', 'Offer "yes, it is play" next to the right answer and ask the question again in a new context.', 'Ask: what happens to the floor and the water?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
